function markReachable(roots, graph) {
  const alive = new Set()
  const stack = [...roots]
  while (stack.length) {
    const id = stack.pop()
    if (alive.has(id)) continue
    alive.add(id)
    for (const next of graph[id] ?? []) stack.push(next)
  }
  return alive
}

